script:
frappe.ui.form.on('Customer', {
	custom_generate_qr(frm){
	   let msg = frappe.msgprint("Generating QR..")
	    frappe.call({
	        method:"icici_collection.icici_collection.doctype.icici_collection.icici_collection.generate_qr",
	        args:{
	            "name":frm.doc.name
	        },
	        callback:(r)=>{
	            frm.doc.custom_qr_text = r.message
	            frm.refresh_field("custom_qr_text")
	            frm.refresh_field("custom_qr_image")
	            frappe.hide_msgprint(msg)
	            frappe.msgprint("QR Generated Successfully")
	        }

	    })
	}
})
